old_signal_use = """                if normalized_entry_type == \"ML_CANDLES_BG\":\n                    countertrend_reason = engine._ml_candles_bg_countertrend_reason(\n                        side=side,\n                        btc_guard=btc_guard,\n                    )\n                    if countertrend_reason:\n                        return False, str(countertrend_reason), effective_probability, btc_following\n                can_open_now, required_min_win = engine._evaluate_hourly_bad_window_guard(\n"""
new_signal_use = """                if normalized_entry_type == \"ML_CANDLES_BG\":\n                    countertrend_reason = engine._ml_candles_bg_countertrend_reason(\n                        side=side,\n                        btc_guard=btc_guard,\n                    )\n                    if countertrend_reason:\n                        return False, str(countertrend_reason), effective_probability, btc_following\n                    effective_probability, _ = engine._apply_ml_candles_btc_regime_pattern_bias(\n                        side=side,\n                        effective_prob=effective_probability,\n                        btc_guard=btc_guard,\n                        pattern_sample=candle_pattern_sample,\n                    )\n                can_open_now, required_min_win = engine._evaluate_hourly_bad_window_guard(\n"""
